    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]

    # Locate the two contiguous border segments on opposite vertical edges.
    def edge_runs(col):
        runs = []
        r = 0
        while r < h:
            if grid[r][col] == bg:
                r += 1
                continue
            color = grid[r][col]
            start = r
            while r + 1 < h and grid[r + 1][col] == color:
                r += 1
            runs.append((color, start, r))
            r += 1
        return runs

    left_runs, right_runs = edge_runs(0), edge_runs(w - 1)
    if not left_runs or not right_runs:
        return [row[:] for row in grid]

    left = max(left_runs, key=lambda run: run[2] - run[1])
    right = max(right_runs, key=lambda run: run[2] - run[1])
    out = [row[:] for row in grid]

    border_colors = {left[0], right[0], bg}
    marker_colors = [c for c in counts if c not in border_colors]
    if not marker_colors:
        return out
    marker_color = marker_colors[0]

    # A marker draws a ray from its segment's border; its row-offset
    # also fills the corresponding row in the opposite border segment.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != marker_color:
                continue

            if left[1] <= r <= left[2]:
                offset = r - left[1]
                paired = right[1] + offset
                if paired <= right[2]:
                    for x in range(w - 1):
                        out[paired][x] = marker_color
                for x in range(1, c):
                    out[r][x] = marker_color
